/*
QueryBot live NL-to-SQL regression fixture - Azure SQL DDL

Run this script first. It is rerunnable and affects only the QBOT_LIVE_TEST
schema. It intentionally contains no GO batch separators.
*/

SET NOCOUNT ON;
SET XACT_ABORT ON;

IF SCHEMA_ID(N'QBOT_LIVE_TEST') IS NULL
    EXEC(N'CREATE SCHEMA [QBOT_LIVE_TEST] AUTHORIZATION [dbo]');

BEGIN TRY
    BEGIN TRANSACTION;

    DROP TABLE IF EXISTS [QBOT_LIVE_TEST].[TEST_EXPECTED_CASES];
    DROP TABLE IF EXISTS [QBOT_LIVE_TEST].[F_BAD_CODE];
    DROP TABLE IF EXISTS [QBOT_LIVE_TEST].[D_DUPLICATE_CODE];
    DROP TABLE IF EXISTS [QBOT_LIVE_TEST].[F_SHIPMENTS];
    DROP TABLE IF EXISTS [QBOT_LIVE_TEST].[F_ORDERS];
    DROP TABLE IF EXISTS [QBOT_LIVE_TEST].[F_RETURNS];
    DROP TABLE IF EXISTS [QBOT_LIVE_TEST].[M3_MITBAL];
    DROP TABLE IF EXISTS [QBOT_LIVE_TEST].[ERP_ITM_BAL_PRD_FCT];
    DROP TABLE IF EXISTS [QBOT_LIVE_TEST].[F_INVENTORY_MONTHLY];
    DROP TABLE IF EXISTS [QBOT_LIVE_TEST].[F_INVENTORY_DAILY];
    DROP TABLE IF EXISTS [QBOT_LIVE_TEST].[F_SALES_INVOICE];
    DROP TABLE IF EXISTS [QBOT_LIVE_TEST].[B_PRODUCT_CATEGORY];
    DROP TABLE IF EXISTS [QBOT_LIVE_TEST].[D_CATEGORY];
    DROP TABLE IF EXISTS [QBOT_LIVE_TEST].[D_PRODUCT];
    DROP TABLE IF EXISTS [QBOT_LIVE_TEST].[D_CUSTOMER_SCD2];
    DROP TABLE IF EXISTS [QBOT_LIVE_TEST].[D_WAREHOUSE];
    DROP TABLE IF EXISTS [QBOT_LIVE_TEST].[D_REGION];
    DROP TABLE IF EXISTS [QBOT_LIVE_TEST].[D_DATE];

    CREATE TABLE [QBOT_LIVE_TEST].[D_DATE] (
        [DATE_SK] int NOT NULL,
        [FULL_DATE] date NOT NULL,
        [YYYYMMDD_KEY] int NOT NULL,
        [YYYYMM_KEY] int NOT NULL,
        [CALENDAR_YEAR] smallint NOT NULL,
        [CALENDAR_QUARTER] tinyint NOT NULL,
        [CALENDAR_MONTH_NUMBER] tinyint NOT NULL,
        [CALENDAR_MONTH_NAME] varchar(12) NOT NULL,
        [MONTH_START_DATE] date NOT NULL,
        [MONTH_END_DATE] date NOT NULL,
        [DAY_OF_MONTH] tinyint NOT NULL,
        [IS_MONTH_END] bit NOT NULL,
        CONSTRAINT [PK_QBOT_LIVE_TEST_D_DATE] PRIMARY KEY ([DATE_SK]),
        CONSTRAINT [UQ_QBOT_LIVE_TEST_D_DATE_FULL_DATE] UNIQUE ([FULL_DATE]),
        CONSTRAINT [UQ_QBOT_LIVE_TEST_D_DATE_YYYYMMDD] UNIQUE ([YYYYMMDD_KEY])
    );

    CREATE TABLE [QBOT_LIVE_TEST].[D_REGION] (
        [REGION_SK] int NOT NULL,
        [REGION_CODE] varchar(12) NOT NULL,
        [REGION_NAME] varchar(80) NOT NULL,
        CONSTRAINT [PK_QBOT_LIVE_TEST_D_REGION] PRIMARY KEY ([REGION_SK]),
        CONSTRAINT [UQ_QBOT_LIVE_TEST_D_REGION_CODE] UNIQUE ([REGION_CODE])
    );

    CREATE TABLE [QBOT_LIVE_TEST].[D_WAREHOUSE] (
        [WAREHOUSE_SK] int NOT NULL,
        [WAREHOUSE_CODE] varchar(12) NOT NULL,
        [WAREHOUSE_NAME] varchar(100) NOT NULL,
        [REGION_SK] int NOT NULL,
        [ACTIVE_FLAG] bit NOT NULL,
        CONSTRAINT [PK_QBOT_LIVE_TEST_D_WAREHOUSE] PRIMARY KEY ([WAREHOUSE_SK]),
        CONSTRAINT [UQ_QBOT_LIVE_TEST_D_WAREHOUSE_CODE] UNIQUE ([WAREHOUSE_CODE]),
        CONSTRAINT [FK_QBOT_LIVE_TEST_WAREHOUSE_REGION] FOREIGN KEY ([REGION_SK])
            REFERENCES [QBOT_LIVE_TEST].[D_REGION] ([REGION_SK])
    );

    CREATE TABLE [QBOT_LIVE_TEST].[D_CUSTOMER_SCD2] (
        [CUSTOMER_SK] int NOT NULL,
        [CUSTOMER_BK] varchar(20) NOT NULL,
        [CUSTOMER_NAME] varchar(120) NOT NULL,
        [CUSTOMER_SEGMENT] varchar(40) NOT NULL,
        [EFFECTIVE_FROM_DATE] date NOT NULL,
        [EFFECTIVE_TO_DATE] date NOT NULL,
        [CURRENT_FLAG] bit NOT NULL,
        CONSTRAINT [PK_QBOT_LIVE_TEST_D_CUSTOMER] PRIMARY KEY ([CUSTOMER_SK]),
        CONSTRAINT [UQ_QBOT_LIVE_TEST_D_CUSTOMER_VERSION]
            UNIQUE ([CUSTOMER_BK], [EFFECTIVE_FROM_DATE])
    );

    CREATE TABLE [QBOT_LIVE_TEST].[D_PRODUCT] (
        [PRODUCT_SK] int NOT NULL,
        [PRODUCT_CODE] varchar(20) NOT NULL,
        [PRODUCT_NAME] varchar(120) NOT NULL,
        [PRODUCT_FAMILY] varchar(50) NOT NULL,
        [UNIT_OF_MEASURE] varchar(10) NOT NULL,
        CONSTRAINT [PK_QBOT_LIVE_TEST_D_PRODUCT] PRIMARY KEY ([PRODUCT_SK]),
        CONSTRAINT [UQ_QBOT_LIVE_TEST_D_PRODUCT_CODE] UNIQUE ([PRODUCT_CODE])
    );

    CREATE TABLE [QBOT_LIVE_TEST].[D_CATEGORY] (
        [CATEGORY_SK] int NOT NULL,
        [CATEGORY_CODE] varchar(20) NOT NULL,
        [CATEGORY_NAME] varchar(100) NOT NULL,
        CONSTRAINT [PK_QBOT_LIVE_TEST_D_CATEGORY] PRIMARY KEY ([CATEGORY_SK]),
        CONSTRAINT [UQ_QBOT_LIVE_TEST_D_CATEGORY_CODE] UNIQUE ([CATEGORY_CODE])
    );

    CREATE TABLE [QBOT_LIVE_TEST].[B_PRODUCT_CATEGORY] (
        [PRODUCT_SK] int NOT NULL,
        [CATEGORY_SK] int NOT NULL,
        [ALLOCATION_PCT] decimal(9,6) NOT NULL,
        CONSTRAINT [PK_QBOT_LIVE_TEST_B_PRODUCT_CATEGORY]
            PRIMARY KEY ([PRODUCT_SK], [CATEGORY_SK]),
        CONSTRAINT [CK_QBOT_LIVE_TEST_B_PRODUCT_CATEGORY_ALLOCATION]
            CHECK ([ALLOCATION_PCT] > 0 AND [ALLOCATION_PCT] <= 1),
        CONSTRAINT [FK_QBOT_LIVE_TEST_BPC_PRODUCT] FOREIGN KEY ([PRODUCT_SK])
            REFERENCES [QBOT_LIVE_TEST].[D_PRODUCT] ([PRODUCT_SK]),
        CONSTRAINT [FK_QBOT_LIVE_TEST_BPC_CATEGORY] FOREIGN KEY ([CATEGORY_SK])
            REFERENCES [QBOT_LIVE_TEST].[D_CATEGORY] ([CATEGORY_SK])
    );

    CREATE TABLE [QBOT_LIVE_TEST].[F_SALES_INVOICE] (
        [SALES_LINE_SK] bigint NOT NULL,
        [INVOICE_NUMBER] varchar(24) NOT NULL,
        [INVOICE_DATE_SK] int NOT NULL,
        [ORDER_DATE_SK] int NOT NULL,
        [POSTING_YYYYMM] int NOT NULL,
        [CUSTOMER_SK] int NOT NULL,
        [PRODUCT_SK] int NOT NULL,
        [WAREHOUSE_SK] int NOT NULL,
        [QUANTITY] decimal(18,3) NOT NULL,
        [GROSS_AMOUNT] decimal(19,4) NOT NULL,
        [DISCOUNT_AMOUNT] decimal(19,4) NOT NULL,
        [NET_REVENUE_AMOUNT] decimal(19,4) NOT NULL,
        [UPDATED_AT_UTC] datetime2(0) NOT NULL,
        CONSTRAINT [PK_QBOT_LIVE_TEST_F_SALES_INVOICE] PRIMARY KEY ([SALES_LINE_SK]),
        CONSTRAINT [CK_QBOT_LIVE_TEST_F_SALES_POSTING_YYYYMM]
            CHECK ([POSTING_YYYYMM] BETWEEN 190001 AND 299912),
        CONSTRAINT [FK_QBOT_LIVE_TEST_SALES_INVOICE_DATE] FOREIGN KEY ([INVOICE_DATE_SK])
            REFERENCES [QBOT_LIVE_TEST].[D_DATE] ([DATE_SK]),
        CONSTRAINT [FK_QBOT_LIVE_TEST_SALES_ORDER_DATE] FOREIGN KEY ([ORDER_DATE_SK])
            REFERENCES [QBOT_LIVE_TEST].[D_DATE] ([DATE_SK]),
        CONSTRAINT [FK_QBOT_LIVE_TEST_SALES_CUSTOMER] FOREIGN KEY ([CUSTOMER_SK])
            REFERENCES [QBOT_LIVE_TEST].[D_CUSTOMER_SCD2] ([CUSTOMER_SK]),
        CONSTRAINT [FK_QBOT_LIVE_TEST_SALES_PRODUCT] FOREIGN KEY ([PRODUCT_SK])
            REFERENCES [QBOT_LIVE_TEST].[D_PRODUCT] ([PRODUCT_SK]),
        CONSTRAINT [FK_QBOT_LIVE_TEST_SALES_WAREHOUSE] FOREIGN KEY ([WAREHOUSE_SK])
            REFERENCES [QBOT_LIVE_TEST].[D_WAREHOUSE] ([WAREHOUSE_SK])
    );

    CREATE TABLE [QBOT_LIVE_TEST].[F_INVENTORY_DAILY] (
        [DAILY_SNAPSHOT_SK] bigint NOT NULL,
        [SNAPSHOT_YYYYMMDD] int NOT NULL,
        [SNAPSHOT_DATE] date NOT NULL,
        [SNAPSHOT_AT_UTC] datetime2(0) NOT NULL,
        [PRODUCT_SK] int NOT NULL,
        [WAREHOUSE_SK] int NOT NULL,
        [ON_HAND_QUANTITY] decimal(18,3) NOT NULL,
        [ALLOCATED_QUANTITY] decimal(18,3) NOT NULL,
        [UNIT_COST] decimal(19,4) NOT NULL,
        [INVENTORY_VALUE] decimal(19,4) NOT NULL,
        CONSTRAINT [PK_QBOT_LIVE_TEST_F_INVENTORY_DAILY] PRIMARY KEY ([DAILY_SNAPSHOT_SK]),
        CONSTRAINT [UQ_QBOT_LIVE_TEST_INVENTORY_DAILY_GRAIN]
            UNIQUE ([SNAPSHOT_YYYYMMDD], [PRODUCT_SK], [WAREHOUSE_SK]),
        CONSTRAINT [CK_QBOT_LIVE_TEST_INVENTORY_DAILY_YYYYMMDD]
            CHECK ([SNAPSHOT_YYYYMMDD] BETWEEN 19000101 AND 29991231),
        CONSTRAINT [FK_QBOT_LIVE_TEST_DAILY_PRODUCT] FOREIGN KEY ([PRODUCT_SK])
            REFERENCES [QBOT_LIVE_TEST].[D_PRODUCT] ([PRODUCT_SK]),
        CONSTRAINT [FK_QBOT_LIVE_TEST_DAILY_WAREHOUSE] FOREIGN KEY ([WAREHOUSE_SK])
            REFERENCES [QBOT_LIVE_TEST].[D_WAREHOUSE] ([WAREHOUSE_SK])
    );

    CREATE TABLE [QBOT_LIVE_TEST].[F_INVENTORY_MONTHLY] (
        [MONTHLY_SNAPSHOT_SK] bigint NOT NULL,
        [PERIOD_YYYYMM] int NOT NULL,
        [PRODUCT_SK] int NOT NULL,
        [WAREHOUSE_SK] int NOT NULL,
        [ENDING_ON_HAND_QUANTITY] decimal(18,3) NOT NULL,
        [ENDING_INVENTORY_VALUE] decimal(19,4) NOT NULL,
        CONSTRAINT [PK_QBOT_LIVE_TEST_F_INVENTORY_MONTHLY] PRIMARY KEY ([MONTHLY_SNAPSHOT_SK]),
        CONSTRAINT [UQ_QBOT_LIVE_TEST_INVENTORY_MONTHLY_GRAIN]
            UNIQUE ([PERIOD_YYYYMM], [PRODUCT_SK], [WAREHOUSE_SK]),
        CONSTRAINT [CK_QBOT_LIVE_TEST_INVENTORY_MONTHLY_YYYYMM]
            CHECK ([PERIOD_YYYYMM] BETWEEN 190001 AND 299912),
        CONSTRAINT [FK_QBOT_LIVE_TEST_MONTHLY_PRODUCT] FOREIGN KEY ([PRODUCT_SK])
            REFERENCES [QBOT_LIVE_TEST].[D_PRODUCT] ([PRODUCT_SK]),
        CONSTRAINT [FK_QBOT_LIVE_TEST_MONTHLY_WAREHOUSE] FOREIGN KEY ([WAREHOUSE_SK])
            REFERENCES [QBOT_LIVE_TEST].[D_WAREHOUSE] ([WAREHOUSE_SK])
    );

    /*
    ERP periodic item-balance fact matching the PRD_DMS_KEY pattern observed
    in production systems. PRD_DMS_KEY is an encoded YYYYMM grain value, not a
    native date and not a surrogate foreign key to D_DATE.
    */
    CREATE TABLE [QBOT_LIVE_TEST].[ERP_ITM_BAL_PRD_FCT] (
        [ITM_BAL_PRD_FCT_KEY] bigint NOT NULL,
        [WHS_DMS_KEY] int NOT NULL,
        [ITM_DMS_KEY] int NOT NULL,
        [PRD_DMS_KEY] int NOT NULL,
        [ON_HND_QTY] decimal(18,3) NOT NULL,
        [ALLOC_QTY] decimal(18,3) NOT NULL,
        [INV_VAL_AMT] decimal(19,4) NOT NULL,
        CONSTRAINT [PK_QBOT_LIVE_TEST_ERP_ITM_BAL_PRD_FCT]
            PRIMARY KEY ([ITM_BAL_PRD_FCT_KEY]),
        CONSTRAINT [UQ_QBOT_LIVE_TEST_ERP_ITM_BAL_PRD_GRAIN]
            UNIQUE ([PRD_DMS_KEY], [ITM_DMS_KEY], [WHS_DMS_KEY]),
        CONSTRAINT [CK_QBOT_LIVE_TEST_ERP_ITM_BAL_PRD_PERIOD]
            CHECK ([PRD_DMS_KEY] = 0 OR [PRD_DMS_KEY] BETWEEN 190001 AND 299912),
        CONSTRAINT [FK_QBOT_LIVE_TEST_ERP_ITM_BAL_PRD_WAREHOUSE]
            FOREIGN KEY ([WHS_DMS_KEY])
            REFERENCES [QBOT_LIVE_TEST].[D_WAREHOUSE] ([WAREHOUSE_SK]),
        CONSTRAINT [FK_QBOT_LIVE_TEST_ERP_ITM_BAL_PRD_PRODUCT]
            FOREIGN KEY ([ITM_DMS_KEY])
            REFERENCES [QBOT_LIVE_TEST].[D_PRODUCT] ([PRODUCT_SK])
    );

    /*
    Infor M3-style cryptic ERP table. MLPERY is YYYYMM, while MLSTQT,
    MLALQT and MLAVAL are stock, allocated quantity and inventory value.
    The keys and constraints provide structural evidence independent of names.
    */
    CREATE TABLE [QBOT_LIVE_TEST].[M3_MITBAL] (
        [MLCONO] smallint NOT NULL,
        [MLWHLO] varchar(12) NOT NULL,
        [MLITNO] varchar(20) NOT NULL,
        [MLPERY] int NOT NULL,
        [MLSTQT] decimal(18,3) NOT NULL,
        [MLALQT] decimal(18,3) NOT NULL,
        [MLAVAL] decimal(19,4) NOT NULL,
        [MLLMDT] int NOT NULL,
        CONSTRAINT [PK_QBOT_LIVE_TEST_M3_MITBAL]
            PRIMARY KEY ([MLCONO], [MLWHLO], [MLITNO], [MLPERY]),
        CONSTRAINT [CK_QBOT_LIVE_TEST_M3_MITBAL_PERIOD]
            CHECK ([MLPERY] BETWEEN 190001 AND 299912),
        CONSTRAINT [CK_QBOT_LIVE_TEST_M3_MITBAL_LAST_MODIFIED]
            CHECK ([MLLMDT] BETWEEN 19000101 AND 29991231),
        CONSTRAINT [FK_QBOT_LIVE_TEST_M3_MITBAL_WAREHOUSE] FOREIGN KEY ([MLWHLO])
            REFERENCES [QBOT_LIVE_TEST].[D_WAREHOUSE] ([WAREHOUSE_CODE]),
        CONSTRAINT [FK_QBOT_LIVE_TEST_M3_MITBAL_PRODUCT] FOREIGN KEY ([MLITNO])
            REFERENCES [QBOT_LIVE_TEST].[D_PRODUCT] ([PRODUCT_CODE])
    );

    CREATE TABLE [QBOT_LIVE_TEST].[F_RETURNS] (
        [RETURN_LINE_SK] bigint NOT NULL,
        [RETURN_NUMBER] varchar(24) NOT NULL,
        [RETURN_DATE_SK] int NOT NULL,
        [ORIGINAL_INVOICE_DATE_SK] int NOT NULL,
        [CUSTOMER_SK] int NOT NULL,
        [PRODUCT_SK] int NOT NULL,
        [WAREHOUSE_SK] int NOT NULL,
        [RETURN_QUANTITY] decimal(18,3) NOT NULL,
        [REFUND_AMOUNT] decimal(19,4) NOT NULL,
        CONSTRAINT [PK_QBOT_LIVE_TEST_F_RETURNS] PRIMARY KEY ([RETURN_LINE_SK]),
        CONSTRAINT [FK_QBOT_LIVE_TEST_RETURN_DATE] FOREIGN KEY ([RETURN_DATE_SK])
            REFERENCES [QBOT_LIVE_TEST].[D_DATE] ([DATE_SK]),
        CONSTRAINT [FK_QBOT_LIVE_TEST_RETURN_INVOICE_DATE] FOREIGN KEY ([ORIGINAL_INVOICE_DATE_SK])
            REFERENCES [QBOT_LIVE_TEST].[D_DATE] ([DATE_SK]),
        CONSTRAINT [FK_QBOT_LIVE_TEST_RETURN_CUSTOMER] FOREIGN KEY ([CUSTOMER_SK])
            REFERENCES [QBOT_LIVE_TEST].[D_CUSTOMER_SCD2] ([CUSTOMER_SK]),
        CONSTRAINT [FK_QBOT_LIVE_TEST_RETURN_PRODUCT] FOREIGN KEY ([PRODUCT_SK])
            REFERENCES [QBOT_LIVE_TEST].[D_PRODUCT] ([PRODUCT_SK]),
        CONSTRAINT [FK_QBOT_LIVE_TEST_RETURN_WAREHOUSE] FOREIGN KEY ([WAREHOUSE_SK])
            REFERENCES [QBOT_LIVE_TEST].[D_WAREHOUSE] ([WAREHOUSE_SK])
    );

    CREATE TABLE [QBOT_LIVE_TEST].[F_ORDERS] (
        [ORDER_SK] bigint NOT NULL,
        [ORDER_NUMBER] varchar(24) NOT NULL,
        [ORDER_DATE_SK] int NOT NULL,
        [CUSTOMER_SK] int NOT NULL,
        [WAREHOUSE_SK] int NOT NULL,
        [ORDER_STATUS] varchar(20) NOT NULL,
        [ORDER_AMOUNT] decimal(19,4) NOT NULL,
        CONSTRAINT [PK_QBOT_LIVE_TEST_F_ORDERS] PRIMARY KEY ([ORDER_SK]),
        CONSTRAINT [UQ_QBOT_LIVE_TEST_F_ORDERS_NUMBER] UNIQUE ([ORDER_NUMBER]),
        CONSTRAINT [FK_QBOT_LIVE_TEST_ORDER_DATE] FOREIGN KEY ([ORDER_DATE_SK])
            REFERENCES [QBOT_LIVE_TEST].[D_DATE] ([DATE_SK]),
        CONSTRAINT [FK_QBOT_LIVE_TEST_ORDER_CUSTOMER] FOREIGN KEY ([CUSTOMER_SK])
            REFERENCES [QBOT_LIVE_TEST].[D_CUSTOMER_SCD2] ([CUSTOMER_SK]),
        CONSTRAINT [FK_QBOT_LIVE_TEST_ORDER_WAREHOUSE] FOREIGN KEY ([WAREHOUSE_SK])
            REFERENCES [QBOT_LIVE_TEST].[D_WAREHOUSE] ([WAREHOUSE_SK])
    );

    CREATE TABLE [QBOT_LIVE_TEST].[F_SHIPMENTS] (
        [SHIPMENT_SK] bigint NOT NULL,
        [SHIPMENT_NUMBER] varchar(24) NOT NULL,
        [ORDER_SK] bigint NOT NULL,
        [SHIPMENT_DATE_SK] int NOT NULL,
        [WAREHOUSE_SK] int NOT NULL,
        [SHIPPED_AMOUNT] decimal(19,4) NOT NULL,
        CONSTRAINT [PK_QBOT_LIVE_TEST_F_SHIPMENTS] PRIMARY KEY ([SHIPMENT_SK]),
        CONSTRAINT [UQ_QBOT_LIVE_TEST_F_SHIPMENTS_NUMBER] UNIQUE ([SHIPMENT_NUMBER]),
        CONSTRAINT [FK_QBOT_LIVE_TEST_SHIPMENT_ORDER] FOREIGN KEY ([ORDER_SK])
            REFERENCES [QBOT_LIVE_TEST].[F_ORDERS] ([ORDER_SK]),
        CONSTRAINT [FK_QBOT_LIVE_TEST_SHIPMENT_DATE] FOREIGN KEY ([SHIPMENT_DATE_SK])
            REFERENCES [QBOT_LIVE_TEST].[D_DATE] ([DATE_SK]),
        CONSTRAINT [FK_QBOT_LIVE_TEST_SHIPMENT_WAREHOUSE] FOREIGN KEY ([WAREHOUSE_SK])
            REFERENCES [QBOT_LIVE_TEST].[D_WAREHOUSE] ([WAREHOUSE_SK])
    );

    /* Intentionally unsafe lookup target: DUP_CODE is not unique. */
    CREATE TABLE [QBOT_LIVE_TEST].[D_DUPLICATE_CODE] (
        [DUPLICATE_CODE_SK] int NOT NULL,
        [DUP_CODE] varchar(12) NOT NULL,
        [DUP_DESCRIPTION] varchar(100) NOT NULL,
        CONSTRAINT [PK_QBOT_LIVE_TEST_D_DUPLICATE_CODE] PRIMARY KEY ([DUPLICATE_CODE_SK])
    );

    CREATE TABLE [QBOT_LIVE_TEST].[F_BAD_CODE] (
        [BAD_FACT_SK] bigint NOT NULL,
        [TARGET_CODE] varchar(12) NOT NULL,
        [MEASURE_AMOUNT] decimal(19,4) NOT NULL,
        CONSTRAINT [PK_QBOT_LIVE_TEST_F_BAD_CODE] PRIMARY KEY ([BAD_FACT_SK])
    );

    CREATE TABLE [QBOT_LIVE_TEST].[TEST_EXPECTED_CASES] (
        [CASE_ID] int NOT NULL,
        [CAPABILITY] varchar(60) NOT NULL,
        [QUESTION_TEXT] nvarchar(500) NOT NULL,
        [EXPECTED_RESULT] nvarchar(1000) NOT NULL,
        [REQUIRED_TABLES] nvarchar(500) NULL,
        [REQUIRED_DATE_ROLE] varchar(80) NULL,
        [FORBIDDEN_BEHAVIOR] nvarchar(500) NULL,
        CONSTRAINT [PK_QBOT_LIVE_TEST_EXPECTED_CASES] PRIMARY KEY ([CASE_ID])
    );

    CREATE INDEX [IX_QBOT_LIVE_TEST_SALES_INVOICE_DATE]
        ON [QBOT_LIVE_TEST].[F_SALES_INVOICE] ([INVOICE_DATE_SK]);
    CREATE INDEX [IX_QBOT_LIVE_TEST_SALES_ORDER_DATE]
        ON [QBOT_LIVE_TEST].[F_SALES_INVOICE] ([ORDER_DATE_SK]);
    CREATE INDEX [IX_QBOT_LIVE_TEST_SALES_WAREHOUSE]
        ON [QBOT_LIVE_TEST].[F_SALES_INVOICE] ([WAREHOUSE_SK]);
    CREATE INDEX [IX_QBOT_LIVE_TEST_DAILY_DATE]
        ON [QBOT_LIVE_TEST].[F_INVENTORY_DAILY] ([SNAPSHOT_YYYYMMDD]);
    CREATE INDEX [IX_QBOT_LIVE_TEST_MONTHLY_PERIOD]
        ON [QBOT_LIVE_TEST].[F_INVENTORY_MONTHLY] ([PERIOD_YYYYMM]);
    CREATE INDEX [IX_QBOT_LIVE_TEST_ERP_ITM_BAL_PRD_PERIOD]
        ON [QBOT_LIVE_TEST].[ERP_ITM_BAL_PRD_FCT] ([PRD_DMS_KEY]);
    CREATE INDEX [IX_QBOT_LIVE_TEST_MITBAL_PERIOD]
        ON [QBOT_LIVE_TEST].[M3_MITBAL] ([MLPERY]);
    CREATE INDEX [IX_QBOT_LIVE_TEST_BAD_CODE]
        ON [QBOT_LIVE_TEST].[F_BAD_CODE] ([TARGET_CODE]);

    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF XACT_STATE() <> 0
        ROLLBACK TRANSACTION;
    THROW;
END CATCH;

SELECT
    s.[name] AS [schema_name],
    COUNT(*) AS [table_count]
FROM sys.tables t
JOIN sys.schemas s ON s.[schema_id] = t.[schema_id]
WHERE s.[name] = N'QBOT_LIVE_TEST'
GROUP BY s.[name];
